def check_fix_frame(frame):
    # Framing-only FIX.4.4 fixture: NOT full field/session/application validation.
    prefix=b"8=FIX.4.4\x019="
    if type(frame) is not bytes or not len(prefix)+9<=len(frame)<=256 or not frame.startswith(prefix):
        raise ValueError("invalid bounded prefix")
    end=frame.find(b"\x01",len(prefix))
    digits=frame[len(prefix):end]
    if end<0 or not 1<=len(digits)<=3 or not digits.isdigit() or digits[:1]==b"0":
        raise ValueError("invalid body length")
    size=int(digits)
    if size>200:
        raise ValueError("body limit")
    trailer=end+1+size
    if len(frame)!=trailer+7 or frame[trailer:trailer+3]!=b"10=" or frame[-1:]!=b"\x01":
        raise ValueError("length or trailer mismatch")
    checksum=frame[trailer+3:trailer+6]
    if not checksum.isdigit() or int(checksum)!=sum(frame[:trailer])%256:
        raise ValueError("checksum mismatch")
    body=frame[end+1:trailer]
    if not body.endswith(b"\x01"):
        raise ValueError("missing body delimiter")
    return body

body=b"35=0\x01" # deliberately framing-only, not a complete valid FIX session message
head=b"8=FIX.4.4\x019="+str(len(body)).encode("ascii")+b"\x01"+body
frame=head+b"10="+f"{sum(head)%256:03d}".encode("ascii")+b"\x01"
print(check_fix_frame(frame)==body)
try:
    check_fix_frame(frame+b"X")
except ValueError as error:
    print(error)
